impl Solution {
    pub fn k_items_with_maximum_sum(num_ones: i32, num_zeros: i32, num_neg_ones: i32, k: i32) -> i32 {
        let ones_to_take = std::cmp::min(k, num_ones);
        let remaining = k - ones_to_take;
        let zeros_to_take = std::cmp::min(remaining, num_zeros);
        let neg_ones_to_take = k - ones_to_take - zeros_to_take;

        let mut sum = 0;
        sum += ones_to_take;
        sum += zeros_to_take * 0;
        if neg_ones_to_take > 0 {
            sum -= neg_ones_to_take;
        }

        sum
    }
}

